        public int[] nextGreaterElement(int[] nums1, int[] nums2) {
            int[] result = new int[nums1.length];
            Map<Integer, Integer> map = new HashMap<>();
            for (int num : nums2) {
                map.put(num, num);
            }
            for (int i = 0; i < nums1.length; i++) {
                int num = nums1[i];
                int nextGreater = -1;
                for (int next : map.keySet()) {
                    if (next > num) {
                        nextGreater = next;
                        break;
                    }
                }
                result[i] = nextGreater;
            }
            return result;
        }
    }
}

